/**
 * Agent Registry Validator — PreToolUse[Agent] Hook
 *
 * Catches a spawn target that will not resolve, BEFORE the dispatch, and says
 * which value is wrong and what the nearest real agent is.
 *
 * The gap it closes: task-agent-advisor falls through to outputSilentSuccess()
 * on any subagent_type it does not recognise, so a typo'd or non-existent agent
 * produced nothing at all. That is how `ork:business-case` (a SKILL, not an
 * agent) died as a generic "parallel[N] failed" with no line naming the cause
 * (#3279), and how /ork:assess shipped four bare names in its default path.
 *
 * ASK, not DENY, on purpose. This is a new check against a registry read from
 * disk; a false positive should be a prompt you can wave through, not a wall.
 * Flip `outputAsk` to `outputDeny` once telemetry shows no false positives —
 * both are one-line swaps and the dispatcher propagates either verbatim
 * (sync-task-dispatcher.ts short-circuits on ask/deny so the prompt is not
 * swallowed into additionalContext).
 *
 * Other plugins' namespaces (vercel:, hq-ext:, ...) pass through untouched: we
 * cannot enumerate their registries and guessing would block valid work.
 *
 * @hook PreToolUse[Agent]
 * @see https://github.com/yonatangross/orchestkit/issues/3279
 */

import type { HookContext, HookInput, HookResult } from '../../types.js';
import { outputAsk, outputSilentSuccess } from '../../lib/common.js';
import { NOOP_CTX } from '../../lib/context.js';
import { explainSpawnTarget } from '../../lib/agent-registry.js';

const HOOK_NAME = 'agent-registry-validator';

export function agentRegistryValidator(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
): HookResult {
  const toolInput = (input.tool_input ?? {}) as Record<string, unknown>;
  const subagentType = toolInput.subagent_type;
  if (typeof subagentType !== 'string' || !subagentType) return outputSilentSuccess();

  let reason: string | null;
  try {
    reason = explainSpawnTarget(subagentType);
  } catch (err) {
    // Fail OPEN. A validator that cannot read the registry must never become
    // the reason a legitimate spawn is blocked.
    ctx.log(HOOK_NAME, `registry read failed, allowing: ${String(err)}`); // silent: fail-open
    return outputSilentSuccess();
  }

  if (!reason) return outputSilentSuccess();

  ctx.log(HOOK_NAME, `invalid spawn target: ${subagentType}`);
  return outputAsk(`[${HOOK_NAME}] ${reason}`);
}
